def main():
    if len(sys.argv) > 1:
        data = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
    else:
        data = json.load(sys.stdin)
    result = scan(data)
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
